package xyz.jovanstoiljkovic.isa.services;import org.springframework.data.repository.CrudRepository;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.stereotype.Service;import xyz.jovanstoiljkovic.isa.dtos.RegisterDTO;import xyz.jovanstoiljkovic.isa.dtos.user.UserDTO;import xyz.jovanstoiljkovic.isa.mappers.UserMapper;import xyz.jovanstoiljkovic.isa.models.User;import xyz.jovanstoiljkovic.isa.repositories.UserRepository;import java.util.Optional;@Servicepublic class UserService extends BaseService<User>{    final private UserRepository userRepository;    final private UserMapper mapper;    private BCryptPasswordEncoder encoder = new BCryptPasswordEncoder(12);    public UserService(UserRepository repo,                       UserMapper mapper) {        super(repo);        this.userRepository = repo;        this.mapper = mapper;    }    public Optional<User> findByUsername(String username){        User user = userRepository.findByUsername(username);        if(user == null) return Optional.empty();        return Optional.of(user);    }    public Optional<UserDTO> register(RegisterDTO registerDTO){        if(userRepository.findByUsername(registerDTO.getUsername()) != null) return Optional.empty();        registerDTO.setPassword(encoder.encode(registerDTO.getPassword()));        User user = mapper.registerToEntity(registerDTO);        UserDTO response = mapper.entityToDTO(repo.save(user));        return Optional.of(response);    }    @Override    public Optional<User> create(User item){        if(userRepository.findByUsername(item.getUsername()) != null) return Optional.empty();        item.setPassword(encoder.encode(item.getPassword()));        repo.save(item);        return Optional.of(item);    }}